// Hand-written `rxjs` stub: an observable, and the calls that gather several into one.

export interface Subscription {
  unsubscribe(): void;
}

export type OperatorFunction<T, R> = (source: Observable<T>) => Observable<R>;

export declare class Observable<T> {
  subscribe(next?: (value: T) => void): Subscription;
  pipe(): Observable<T>;
  pipe<A>(op1: OperatorFunction<T, A>): Observable<A>;
}

export declare function forkJoin<A, B>(sources: [Observable<A>, Observable<B>]): Observable<[A, B]>;
export declare function forkJoin<T extends Record<string, Observable<unknown>>>(sources: T): Observable<{ [K in keyof T]: T[K] extends Observable<infer V> ? V : never }>;
export declare function map<T, R>(project: (value: T) => R): OperatorFunction<T, R>;
